    #Node Math
    def math(
        self,
        radians: Float=None,
        degrees: Float=None,
        base: Float=None,
        threshold: Float=None,
        value_1: Float=None,
        base_1: Float=None,
        multiplier: Float=None,
        increment: Float=None,
        max: Float=None,
        exponent: Float=None,
        scale: Float=None,
        addend: Float=None,
        value_2: Float=None,
        min: Float=None,
        distance: Float=None,
        epsilon: Float=None,
        operation: T_OPERATION_3='ADD'):
        """Node Math.
        
        Jump: False

        **Fixed inputs**

        - self on socket 'Value'

        Parameters
        ----------
        radians : Float, optional
            Socket 'Radians', identifier 'Value' (default: None)
        degrees : Float, optional
            Socket 'Degrees', identifier 'Value' (default: None)
        base : Float, optional
            Socket 'Base', identifier 'Value' (default: None)
        threshold : Float, optional
            Socket 'Threshold', identifier 'Value_001' (default: None)
        value_1 : Float, optional
            Socket 'Value', identifier 'Value_001' (default: None)
        base_1 : Float, optional
            Socket 'Base', identifier 'Value_001' (default: None)
        multiplier : Float, optional
            Socket 'Multiplier', identifier 'Value_001' (default: None)
        increment : Float, optional
            Socket 'Increment', identifier 'Value_001' (default: None)
        max : Float, optional
            Socket 'Max', identifier 'Value_001' (default: None)
        exponent : Float, optional
            Socket 'Exponent', identifier 'Value_001' (default: None)
        scale : Float, optional
            Socket 'Scale', identifier 'Value_001' (default: None)
        addend : Float, optional
            Socket 'Addend', identifier 'Value_002' (default: None)
        value_2 : Float, optional
            Socket 'Value', identifier 'Value_002' (default: None)
        min : Float, optional
            Socket 'Min', identifier 'Value_002' (default: None)
        distance : Float, optional
            Socket 'Distance', identifier 'Value_002' (default: None)
        epsilon : Float, optional
            Socket 'Epsilon', identifier 'Value_002' (default: None)
        operation : {'ADD', 'SUBTRACT', 'MULTIPLY', 'DIVIDE', 'MULTIPLY_ADD', 'POWER', 'LOGARITHM', 'SQRT', 'INVERSE_SQRT', 'ABSOLUTE', 'EXPONENT', 'MINIMUM', 'MAXIMUM', 'LESS_THAN', 'GREATER_THAN', 'SIGN', 'COMPARE', 'SMOOTH_MIN', 'SMOOTH_MAX', 'ROUND', 'FLOOR', 'CEIL', 'TRUNC', 'FRACT', 'MODULO', 'FLOORED_MODULO', 'WRAP', 'SNAP', 'PINGPONG', 'SINE', 'COSINE', 'TANGENT', 'ARCSINE', 'ARCCOSINE', 'ARCTANGENT', 'ARCTAN2', 'SINH', 'COSH', 'TANH', 'RADIANS', 'DEGREES'}, optional
            Node parameter 'operation' (default: 'ADD')

        Returns
        -------
        Socket
            Default output socket.
        """
        named_sockets = {'ID_Value': self}
        named_sockets['ID_Value'] = None
        if radians is not None: named_sockets['ID_Value'] = radians
        if degrees is not None: named_sockets['ID_Value'] = degrees
        if base is not None: named_sockets['ID_Value'] = base
        named_sockets['ID_Value_001'] = None
        if threshold is not None: named_sockets['ID_Value_001'] = threshold
        if value_1 is not None: named_sockets['ID_Value_001'] = value_1
        if base_1 is not None: named_sockets['ID_Value_001'] = base_1
        if multiplier is not None: named_sockets['ID_Value_001'] = multiplier
        if increment is not None: named_sockets['ID_Value_001'] = increment
        if max is not None: named_sockets['ID_Value_001'] = max
        if exponent is not None: named_sockets['ID_Value_001'] = exponent
        if scale is not None: named_sockets['ID_Value_001'] = scale
        named_sockets['ID_Value_002'] = None
        if addend is not None: named_sockets['ID_Value_002'] = addend
        if value_2 is not None: named_sockets['ID_Value_002'] = value_2
        if min is not None: named_sockets['ID_Value_002'] = min
        if distance is not None: named_sockets['ID_Value_002'] = distance
        if epsilon is not None: named_sockets['ID_Value_002'] = epsilon

        node = Node( 'Math', named_sockets=named_sockets, operation=operation)
        return node._out

